static inline S_MirRecord *s_mir_record_new(int64_t id, size_t fields) {
	if (fields > (SIZE_MAX - sizeof(S_MirRecord)) / sizeof(S_MirField)) s_panic("collection too large");
	S_MirRecord *r = calloc(1, sizeof(S_MirRecord) + fields * sizeof(S_MirField));
	if (!r) s_panic("out of memory");
	r->type_id = id; r->refs = 1; s_arc_audit_new(r, r->refs); s_arc_audit_watch(r, s_mir_record_arc_scan); r->length = fields; r->capacity = fields; return r;
}
static inline S_MirRecord *s_mir_record_retain(S_MirRecord *r) { if (r) { ++r->refs; s_arc_audit_retain(r, r->refs); } return r; }
static inline S_MirRecord *s_mir_record_reserve_owned(S_MirRecord *r, size_t need) {
	if (need <= r->capacity) return r;
	const size_t limit = (SIZE_MAX - sizeof(S_MirRecord)) / sizeof(S_MirField);
	if (need > limit) s_panic("collection too large");
	size_t capacity = r->capacity ? r->capacity : 4;
	while (capacity < need) capacity = capacity > limit / 2 ? limit : capacity * 2;
	uintptr_t previous = (uintptr_t)r;
	S_MirRecord *grown = realloc(r, sizeof(S_MirRecord) + capacity * sizeof(S_MirField));
	if (!grown) s_panic("out of memory");
	s_arc_audit_relocate(previous, grown); grown->capacity = capacity; return grown;
}
static inline S_String *s_mir_string_join(const S_String *sep, const S_MirRecord *parts) {
	size_t total = 0;
	for (size_t i = 0; i < parts->length; ++i) {
		const size_t n = parts->fields[i].text->length;
		if (n > SIZE_MAX - total - sizeof(S_String) - 1) s_panic("string too large");
		total += n;
		if (i) { if (sep->length > SIZE_MAX - total - sizeof(S_String) - 1) s_panic("string too large"); total += sep->length; }
	}
	S_String *out = malloc(sizeof(S_String) + total + 1);
	if (!out) s_panic("out of memory");
	out->refcount = 1; s_arc_audit_new(out, out->refcount); out->length = total;
	size_t at = 0;
	for (size_t i = 0; i < parts->length; ++i) {
		if (i) { memcpy(out->data + at, sep->data, sep->length); at += sep->length; }
		const S_String *item = parts->fields[i].text;
		memcpy(out->data + at, item->data, item->length); at += item->length;
	}
	out->data[total] = '\0';
	return out;
}
static inline S_MirRecord *s_mir_arguments(int64_t type_id) {
	S_Array *args = s_arguments();
	size_t count = s_array_length(args);
	S_MirRecord *out = s_mir_record_new(type_id, count);
	for (size_t i = 0; i < count; ++i) out->fields[i].text = s_string_retain(*(S_String *const *)s_array_at(args, (int64_t)i));
	s_array_release(args);
	return out;
}
static inline void s_mir_copy_string(void *dst, const void *src) { ((S_MirField *)dst)->text = s_string_retain(((const S_MirField *)src)->text); }
static inline void s_mir_drop_string(void *value) { s_string_release(((S_MirField *)value)->text); }
static inline void s_mir_copy_record(void *dst, const void *src) { ((S_MirField *)dst)->record = s_mir_record_retain(((const S_MirField *)src)->record); }
